import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import axios from "axios";

export default function Login() {
  const navigate = useNavigate();

  const [loginData, setLoginData] = useState({
    email: "",
    password: "",
  });

  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // =========================
  // HANDLE INPUT
  // =========================

  const handleChange = (e) => {
    const { name, value } = e.target;

    setLoginData((prev) => ({
      ...prev,
      [name]: value,
    }));

    // Remove error when user starts typing
    if (error) {
      setError("");
    }
  };

  // =========================
  // HANDLE LOGIN
  // =========================

  const handleLogin = async (e) => {
    e.preventDefault();

    setError("");

    const email = loginData.email.trim();
    const password = loginData.password;

    // =========================
    // BASIC VALIDATION
    // =========================

    if (!email || !password) {
      setError("Please enter your email and password.");
      return;
    }

    if (!email.includes("@")) {
      setError("Please enter a valid email address.");
      return;
    }

    try {
      setLoading(true);

      const response = await axios.post(
        "http://localhost:5000/api/v1/auth/login",
        {
          email: email.toLowerCase(),
          password: password,
        }
      );

      console.log("Login Response:", response.data);

      // =========================
      // GET LOGIN DATA
      // =========================

      const loginResponse = response.data?.data;

      const token = loginResponse?.token;
      const customer = loginResponse?.customer;

      if (!token) {
        throw new Error(
          "Token was not received from server."
        );
      }

      // =========================
      // SAVE TOKEN
      // =========================

      localStorage.setItem("token", token);

      // =========================
      // SAVE CUSTOMER
      // =========================

      if (customer) {
        localStorage.setItem(
          "customer",
          JSON.stringify(customer)
        );

        // Optional user storage
        localStorage.setItem(
          "user",
          JSON.stringify(customer)
        );
      }

      // =========================
      // SUCCESS
      // =========================

      navigate("/dashboard");

    } catch (error) {
      console.log(
        "Login Error:",
        error.response?.data || error.message
      );

      setError(
        error.response?.data?.message ||
        "Invalid email or password. Please try again."
      );

    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container-fluid min-vh-100 bg-light d-flex align-items-center justify-content-center py-4">

      <div className="row w-100 justify-content-center">

        <div className="col-12 col-sm-10 col-md-7 col-lg-5 col-xl-4">

          {/* =========================
              LOGIN CARD
          ========================= */}

          <div className="card border-0 shadow-lg rounded-4">

            <div className="card-body p-4 p-md-5">

              {/* =========================
                  HEADER
              ========================= */}

              <div className="text-center mb-4">

                <div
                  className="bg-primary text-white rounded-4 d-inline-flex align-items-center justify-content-center mb-3 shadow-sm"
                  style={{
                    width: "62px",
                    height: "62px",
                    fontSize: "25px",
                  }}
                >
                  🔐
                </div>

                <h2 className="fw-bold mb-1">
                  Welcome Back
                </h2>

                <p className="text-muted mb-0">
                  Sign in to continue to ShopNest
                </p>

              </div>

              {/* =========================
                  ERROR MESSAGE
              ========================= */}

              {error && (
                <div
                  className="alert alert-danger d-flex align-items-center gap-2 py-2"
                  role="alert"
                >
                  <span>!</span>
                  <small>{error}</small>
                </div>
              )}

              {/* =========================
                  FORM
              ========================= */}

              <form onSubmit={handleLogin}>

                {/* =========================
                    EMAIL
                ========================= */}

                <div className="mb-3">

                  <label
                    htmlFor="email"
                    className="form-label fw-semibold"
                  >
                    Email Address
                  </label>

                  <input
                    id="email"
                    type="email"
                    name="email"
                    className="form-control form-control-lg"
                    placeholder="Enter your email"
                    value={loginData.email}
                    onChange={handleChange}
                    autoComplete="email"
                    disabled={loading}
                    required
                  />

                </div>

                {/* =========================
                    PASSWORD
                ========================= */}

                <div className="mb-2">

                  <label
                    htmlFor="password"
                    className="form-label fw-semibold"
                  >
                    Password
                  </label>

                  <div className="input-group input-group-lg">

                    <input
                      id="password"
                      type={
                        showPassword
                          ? "text"
                          : "password"
                      }
                      name="password"
                      className="form-control"
                      placeholder="Enter your password"
                      value={loginData.password}
                      onChange={handleChange}
                      autoComplete="current-password"
                      disabled={loading}
                      required
                    />

                    <button
                      type="button"
                      className="btn btn-outline-secondary"
                      onClick={() =>
                        setShowPassword(
                          !showPassword
                        )
                      }
                      disabled={loading}
                    >
                      {showPassword
                        ? "Hide"
                        : "Show"}
                    </button>

                  </div>

                </div>

                {/* =========================
                    FORGOT PASSWORD
                ========================= */}

                <div className="text-end mb-4">

                  <Link
                    to="/forgotpassword"
                    className="text-primary text-decoration-none small fw-semibold"
                  >
                    Forgot Password?
                  </Link>

                </div>

                {/* =========================
                    LOGIN BUTTON
                ========================= */}

                <button
                  type="submit"
                  className="btn btn-primary btn-lg w-100 fw-semibold"
                  disabled={loading}
                >

                  {loading ? (
                    <>
                      <span
                        className="spinner-border spinner-border-sm me-2"
                        role="status"
                        aria-hidden="true"
                      ></span>

                      Signing in...
                    </>
                  ) : (
                    <>
                      Login
                      <span className="ms-2">
                        →
                      </span>
                    </>
                  )}

                </button>

              </form>

              {/* =========================
                  REGISTER
              ========================= */}

              <div className="text-center mt-4">

                <span className="text-muted small">
                  Don't have an account?{" "}
                </span>

                <Link
                  to="/register"
                  className="fw-semibold text-primary text-decoration-none"
                >
                  Create Account
                </Link>

              </div>

              {/* =========================
                  SECURITY TEXT
              ========================= */}

              <div className="text-center mt-4">

                <small className="text-muted">
                  🔒 Your account information is
                  securely protected.
                </small>

              </div>

            </div>

          </div>

          {/* =========================
              FOOTER
          ========================= */}

          <p className="text-center text-muted small mt-3 mb-0">
            © 2026 ShopNest. All rights reserved.
          </p>

        </div>

      </div>

    </div>
  );
}
